import { createContext } from "svelte";
import type { MotionValue } from "motion-sv";

export type SlideToUnlockContextValue = {
	readonly x: MotionValue<number>;
	trackRef: HTMLDivElement | null;
	readonly isDragging: boolean;
	readonly handleWidth: number;
	readonly textOpacity: MotionValue<number>;
	onDragStart: () => void;
	onDragEnd: () => void;
};

const [getSlideToUnlockContext, setSlideToUnlockContext] =
	createContext<SlideToUnlockContextValue>();

export function useSlideToUnlock() {
	try {
		return getSlideToUnlockContext();
	} catch {
		throw new Error(
			"SlideToUnlock components must be used within SlideToUnlock"
		);
	}
}

export { setSlideToUnlockContext };

import Root from "./slide-to-unlock.svelte";
import Track from "./slide-to-unlock-track.svelte";
import Text from "./slide-to-unlock-text.svelte";
import Handle from "./slide-to-unlock-handle.svelte";

export {
	Root,
	Track,
	Text,
	Handle,
	//
	Root as SlideToUnlock,
	Track as SlideToUnlockTrack,
	Text as SlideToUnlockText,
	Handle as SlideToUnlockHandle
};

export type { SlideToUnlockProps } from "./slide-to-unlock.svelte";
export type { SlideToUnlockTrackProps } from "./slide-to-unlock-track.svelte";
export type { SlideToUnlockTextProps } from "./slide-to-unlock-text.svelte";
export type { SlideToUnlockHandleProps } from "./slide-to-unlock-handle.svelte";
